from __future__ import annotations

import subprocess

import typer
from ds.cli.util import run_cmd
from ds.util.const import REPO_DIR

__all__ = ["publish_cmd"]


REPO_ROOT = str(REPO_DIR)


def _get_staged_files(cwd: str) -> list[str]:
    """Return staged file paths from git index."""
    result = subprocess.run(
        ["git", "diff", "--cached", "--name-only"],
        capture_output=True,
        text=True,
        check=True,
        cwd=cwd,
    )
    return [line.strip() for line in result.stdout.splitlines() if line.strip()]


def publish_cmd(message: str | None = typer.Option(None, "--message", "-m")) -> None:
    """Publish changes to be deployed"""
    run_cmd(["git", "status", "--short"], cwd=REPO_ROOT)

    add_all = typer.confirm(
        "Add all current changes (staged, unstaged, and untracked) before publish?",
        default=True,
    )
    if add_all:
        run_cmd(["git", "add", "-A"], cwd=REPO_ROOT)

    staged_files = _get_staged_files(cwd=REPO_ROOT)
    if not staged_files:
        typer.echo("No staged changes found after selection. Nothing to publish.")
        raise typer.Exit(code=1)

    if not typer.confirm("Publish these staged changes shown above?", default=True):
        typer.echo("Publish cancelled.")
        raise typer.Exit(code=0)

    commit_message = message or typer.prompt("Commit message")
    run_cmd(["git", "commit", "-m", commit_message], cwd=REPO_ROOT)
    run_cmd(["git", "push"], cwd=REPO_ROOT)
